WHEN EXISTS (SELECT 1 FROM slots s WHERE s.doctor_id = NEW.doctor_id AND s.starts_at < datetime(NEW.starts_at, '+' || NEW.minutes || ' minutes') AND NEW.starts_at < datetime(s.starts_at, '+' || s.minutes || ' minutes'))
